export const SharePassParams = zod.object({
  id: zod.coerce.string().uuid(),
});

export const sharePassBodyOpenSeatsMin = 0;
export const sharePassBodyOpenSeatsMax = 8;

export const SharePassBody = zod.object({
  caption: zod.string().optional(),
  visibility: zod.enum(["private", "link", "friends", "public"]),
  openSeats: zod
    .number()
    .min(sharePassBodyOpenSeatsMin)
    .max(sharePassBodyOpenSeatsMax)
    .optional(),
  seatsClosesAt: zod.string().nullish(),
});

